            @check @dispatch(device, vkGetEncodedVideoSessionParametersKHR(device, video_session_parameters_info, feedback_info, pDataSize, C_NULL))
            pData = Libc.malloc(pDataSize[])
            @check @dispatch(device, vkGetEncodedVideoSessionParametersKHR(device, video_session_parameters_info, feedback_info, pDataSize, pData))
