    pValidationCache = Ref{VkValidationCacheEXT}()
    @check vkCreateValidationCacheEXT(device, create_info, allocator, pValidationCache, fptr_create)
    ValidationCacheEXT(pValidationCache[], begin
            parent = Vk.handle(device)
