function _get_encoded_video_session_parameters_khr(device, video_session_parameters_info::_VideoEncodeSessionParametersGetInfoKHR, fptr::FunctionPtr; feedback_info = C_NULL)::ResultTypes.Result{Tuple{UInt, Ptr{Cvoid}}, VulkanError}
    pDataSize = Ref{UInt}()
    @repeat_while_incomplete begin
            @check vkGetEncodedVideoSessionParametersKHR(device, video_session_parameters_info, feedback_info, pDataSize, C_NULL, fptr)
            pData = Libc.malloc(pDataSize[])
            @check vkGetEncodedVideoSessionParametersKHR(device, video_session_parameters_info, feedback_info, pDataSize, pData, fptr)
            if _return_code == VK_INCOMPLETE
                Libc.free(pData)
            end
        end
    (pDataSize[], pData)
end

