function _get_shader_binary_data_ext(device, shader, fptr::FunctionPtr)::ResultTypes.Result{Tuple{UInt, Ptr{Cvoid}}, VulkanError}
    pDataSize = Ref{UInt}()
    @repeat_while_incomplete begin
            @check vkGetShaderBinaryDataEXT(device, shader, pDataSize, C_NULL, fptr)
            pData = Libc.malloc(pDataSize[])
            @check vkGetShaderBinaryDataEXT(device, shader, pDataSize, pData, fptr)
            if _return_code == VK_INCOMPLETE
                Libc.free(pData)
            end
        end
    (pDataSize[], pData)
end

